import{_ as t,c as a,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易本義通釋","description":"周易本義通釋 - 周易本義通釋","frontmatter":{"title":"周易本義通釋","description":"周易本義通釋 - 周易本義通釋"},"headers":[],"relativePath":"classics/benyi-tongshi/001.md","filePath":"classics/benyi-tongshi/001.md"}'),i={name:"classics/benyi-tongshi/001.md"};function n(r,e,o,c,_,l){return s(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="周易本義通釋" tabindex="-1">周易本義通釋 <a class="header-anchor" href="#周易本義通釋" aria-label="Permalink to “周易本義通釋”">​</a></h1><p>欽定四庫全書經部一</p><p>易類提要</p><p>臣 等謹案：周易本義通釋十二卷，元胡炳文撰。炳文字仲虎，婺源人。新安文獻志以為「篤志朱子之學者也。羲文先後天之易，邵子於先天明其畫，程子於後天演其辭。然邵、程同時並地，其說絕不相謀。自朱子比而合之，理數始備。炳文復取朱子之書，折衷是正，參以諸家易解，以互相發明。初名精義，後病其繁冗，刪而約之，改名通釋。說者謂非本義無以見易，非通釋亦無以盡本義之旨。主一先生之言，以盡廢諸家，雖未免於太狹，然宋儒說易，其途至雜，言數者或失之巧，言理者或失之鑿。求其平正通達，顯有門徑可循者，終以朱子為得中。則炳文羽翼之功，亦未可沒矣。乾隆四十六年九月恭校上。</p><p>總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易本義通釋例</p><p>一先是集諸家易解，名曰精義，然未免失之太繁。竊惟學有統一，易至程朱，明且備矣。本義於程，又能足其所未圓，白其所未瑩，貫其所未一，於是一以本義為主，而謂之通釋。</p><p>一，通釋之於本義，依朱子集註例，蓋集諸家之注為之也。精義中取有合於本義者，或一字，或一句，或一段，或用其意，不用其辭，以故不可出。」諸家名氏己見附其中，亦不表以愚謂。</p><p>一，通釋之名，從勉齋黃氏例。</p><p>一、觀朱子語錄，本義有未改正者，今通釋輒從朱子之志雲。</p>',9)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
